package main
import("fmt";"strings";m "github.com/grafov/m3u8")
func main(){text:="#EXTM3U\n#EXT-X-VERSION:9\n#EXT-X-TARGETDURATION:2\n#EXT-X-MEDIA-SEQUENCE:100\n#EXTINF:2,\nv100.ts\n#EXT-X-RENDITION-REPORT:URI=\"audio.m3u8\",LAST-MSN=700,LAST-PART=0\n";p,t,e:=m.DecodeFrom(strings.NewReader(text),true);if e!=nil||t!=m.MEDIA{panic("production DecodeFrom failed")};v:=p.(*m.MediaPlaylist);if v.Count()!=1||v.SeqNo!=100{panic("media window mismatch")};encoded:=v.Encode().String();r,t,e:=m.DecodeFrom(strings.NewReader(encoded),true);if e!=nil||t!=m.MEDIA||r.(*m.MediaPlaylist).Count()!=1{panic("roundtrip mismatch")};fmt.Printf("baseline sequence=%d count=%d\n",v.SeqNo,v.Count());fmt.Printf("baseline rendition-report retained=%v\n",strings.Contains(encoded,"#EXT-X-RENDITION-REPORT:"));v.Slide("v101.ts",2,"");if v.Count()!=2{panic("append path mismatch")};fmt.Println("baseline media decode/encode/slide: ok")}
